const operations = {
  "+": (left, right) => left + right, "-": (left, right) => left - right,
  "*": (left, right) => left * right, "/": (left, right) => left / right,
};
export function rpnEval(tokens) {
  if (!Array.isArray(tokens) || tokens.length === 0) throw new Error("invalid_expression");
  const stack = [];
  for (const token of tokens) {
    if (typeof token === "number" && Number.isFinite(token)) { stack.push(token); continue; }
    if (typeof token !== "string" || !Object.hasOwn(operations, token)) throw new Error("invalid_token");
    if (stack.length < 2) throw new Error("invalid_expression");
    const right = stack.pop(); const left = stack.pop(); stack.push(operations[token](left, right));
  }
  if (stack.length !== 1) throw new Error("invalid_expression");
  return stack[0];
}

