// case {{CASE_ID}}
const completed = new Map();
export async function performWithRetry(id, operation, record, attempts = 3) {
  if (completed.has(id)) return completed.get(id);
  let last;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      const receipt = await operation();
      completed.set(id, receipt); record(receipt); return receipt;
    } catch (error) {
      if (error?.committed === true && error.receipt !== undefined) {
        completed.set(id, error.receipt); record(error.receipt); return error.receipt;
      }
      last = error;
    }
  }
  throw last;
}
export function resetForTest() { completed.clear(); }

